INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Sip & Build With AI: Meet the Founders of AI Sol Circle', 'AI Sol Circle | Women Building With AI in South Florida', 'Business Start Ups', 'Close the laptop at five and come build something for yourself. You keep hearing that AI will change your career or your business. What', 'Close the laptop at five and come build something for yourself. You keep hearing that AI will change your career or your business. What nobody hands you is a room where you can figure out what that means for you, next to women who are working it out too. This is that room. Join the founders of AI Sol Circle for a relaxed evening at Total Wine & More: a complimentary wine tasting, a short hands-on LinkedIn workshop, and time to bring your real problem and solve it with AI, with us beside you. More info: https://www.meetup.com/ai-sol-circle-women-building-with-ai-in-south-florida/events/316863267/', '2026-10-19T17:00:00-04:00', 'Total Wine & More', '5050 Town Center Cir, Boca Raton, FL 33486, USA', 'Boca Raton', 'FL', '33486', 26.363067318597, -80.121983543725, 'AI Sol Circle | Women Building With AI in South Florida', 4, false, 'Free', 'live', 'meetup', 'https://www.meetup.com/ai-sol-circle-women-building-with-ai-in-south-florida/events/316863267/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
