INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Special Congolese Drumming Seminar', 'Central Florida Drum Circles', 'General Networking', '[Check out a sample of Tam Tam Congo doing a Congolese Rumba known as Tshatsho at the 4 minute mark of this video link!', '[Check out a sample of Tam Tam Congo doing a Congolese Rumba known as Tshatsho at the 4 minute mark of this video link! ](https://youtu.be/peSF8e9PkjU?si=i1QOpeEpSV8POpuf) Thobos Lubamba is the creative director of Tam Tam Congo. He was born into rhythm in his village of the Congo and honed his craft with the **Ballet Mansia** (specifically exploring *Tradition Manianga*), a traditional Congolese drum and dance ensemble. He is recognized as a Congolese **scholarship artist and musician**, More info: https://www.meetup.com/central-florida-drum-circles/events/316843484/', '2026-10-24T15:00:00-04:00', '1660 Cedar Glen Drive', '1660 Cedar Glen Dr, Apopka, FL 32712, USA', 'Apopka', 'FL', '32712', 28.709372890412, -81.500305629183, 'Central Florida Drum Circles', 6, false, 'Free', 'live', 'meetup', 'https://www.meetup.com/central-florida-drum-circles/events/316843484/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Fix and Flip Series : Time Hacks', 'Central Florida Real Estate Agent Accelerator', 'Real Estate Meetings', 'MONDAY 5 PM PST 7 PM CST 8 PM EST [SIGN UP HERE](https://link.elitereimm.com/widget/form/wSbrsstjtpMx77vSSif7?am_id=debbie5574) Use CRM,', 'MONDAY 5 PM PST 7 PM CST 8 PM EST [SIGN UP HERE](https://link.elitereimm.com/widget/form/wSbrsstjtpMx77vSSif7?am_id=debbie5574) Use CRM, systems, automation, and AI to run flips more efficiently without letting every project take over your life. Fixing and flipping can become a full-time job fast. Contractors need answers. Materials need to be ordered. Draws need to be tracked. Budgets change. Inspections get scheduled. Properties need to be marketed. And somehow you are still supposed to find More info: https://www.meetup.com/central-florida-real-estate-agent-accelerator/events/316780079/', '2026-10-12T20:00:00-04:00', 'Online event', 'Online event', 'Orlando', 'FL', '', 28.55, -81.18, 'Central Florida Real Estate Agent Accelerator', 2, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/central-florida-real-estate-agent-accelerator/events/316780079/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('[Virtual] Simple Real Estate Strategies That Work (Fun, Free, & Gets You Paid!)', 'Central Florida Real Estate Agent Accelerator', 'Real Estate Meetings', '**Most real estate trainings are like bad lectures:** boring, overloaded with information, and leaving you feeling like you’ll need weeks', '**Most real estate trainings are like bad lectures:** boring, overloaded with information, and leaving you feeling like you’ll need weeks of prep just to get started (or worst of all, they just want to sell you their expensive course or coaching). **We decided to do the exact opposite**—and hundreds of agents now agree. Join us **LIVE (virtual) every Wednesday at 9:00 AM CST** for a zero-fluff, action-packed call where active, top-producing agents openly share exactly what’s working right More info: https://www.meetup.com/central-florida-real-estate-agent-accelerator/events/316694248/', '2026-10-14T10:00:00-04:00', 'Online event', 'Online event', 'Orlando', 'FL', '', 28.55, -81.18, 'Central Florida Real Estate Agent Accelerator', 1, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/central-florida-real-estate-agent-accelerator/events/316694248/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('RE-AI Advantage Lab: Turn AI Into Your Real Estate Advantage', 'Central Florida Real Estate Agent Accelerator', 'Real Estate Meetings', 'AI is changing what “work” looks like for real estate agents. Tasks that used to take hours can now take minutes. Marketing can be created', 'AI is changing what “work” looks like for real estate agents. Tasks that used to take hours can now take minutes. Marketing can be created faster. Follow up can be smarter. Content can be generated almost instantly. But most agents are still trying to figure out **how to actually use AI in their day-to-day business.** That is exactly what we will be exploring inside the **RE-AI Advantage Lab.** This weekly training is designed specifically for real estate agents who want to learn how to use AI More info: https://www.meetup.com/central-florida-real-estate-agent-accelerator/events/316694911/', '2026-10-14T11:00:00-04:00', 'Online event', 'Online event', 'Orlando', 'FL', '', 28.55, -81.18, 'Central Florida Real Estate Agent Accelerator', 1, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/central-florida-real-estate-agent-accelerator/events/316694911/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Real Estate Agent Virtual Coffee Mastermind', 'Central Florida Real Estate Agent Accelerator', 'Real Estate Meetings', '**Start your morning...** with a coffee & friends from all over the country. Don''t miss out on our live (virtual) networking event every', '**Start your morning...** with a coffee & friends from all over the country. Don''t miss out on our live (virtual) networking event every Thursday morning. It''s the perfect opportunity to build relationships with Realtors across the state and across the country (sometimes even on the other side of the world) that will serve your clients well when they need a referral. We have a short educational/informative presentation at the beginning of the meeting and then go into 3 or 4 person breakout More info: https://www.meetup.com/central-florida-real-estate-agent-accelerator/events/316709353/', '2026-10-15T10:00:00-04:00', 'Online event', 'Online event', 'Orlando', 'FL', '', 28.55, -81.18, 'Central Florida Real Estate Agent Accelerator', 1, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/central-florida-real-estate-agent-accelerator/events/316709353/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
