INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Shepard Park Sunset Drum Circle.', 'Delray Beach Drum Circle', 'General Networking', 'Every Sunday Evening • starts two hours before sunset (could be 3pm in the winter or 6pm in the summer) 3pm Nov - Feb 4:00pm Mar - April', 'Every Sunday Evening • starts two hours before sunset (could be 3pm in the winter or 6pm in the summer) 3pm Nov - Feb 4:00pm Mar - April 6pm May - Aug 4:00 Sept - Oct This drum circle has been happening since 1995! The attendance of this meetup is not accurate, many people faithfully attend this event regularly. Beautiful sunsets overlooking the St Lucie River When the dancers attend, this place sizzles. DIRECTIONS: 1. Take I-95 northbound 2. Exit #101 (FL76 north) 3. After 5.7 miles, turn More info: https://www.meetup.com/delraybeachdrumcircle/events/316757328/', '2026-10-18T18:00:00-04:00', '601 Southwest Ocean Boulevard', '601 Southwest Ocean Boulevard  Stuart, FL 34994', 'Stuart', 'FL', '34994', 27.197647639938, -80.258066017199, 'Delray Beach Drum Circle', 0, false, 'Free', 'live', 'meetup', 'https://www.meetup.com/delraybeachdrumcircle/events/316757328/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('[Hybrid] Discussion: Two Sides of Design Autonomy', 'DOUX — Downtown Orlando UX Meetup', 'General Networking', 'For years, designers have said they''d do better work if the organization got out of the way. AI is enabling us to test that claim. In his', 'For years, designers have said they''d do better work if the organization got out of the way. AI is enabling us to test that claim. In his recent [Smashing Magazine article](https://www.smashingmagazine.com/2026/07/bull-and-bear-case-digital-design-age-ai/), Andy Budd lays out two futures. In the bull case, designers can go from "we should fix this" to "I fixed this, and pushed it live," and need far less permission to act. In the bear case, that same autonomy exposes designers who were better More info: https://www.meetup.com/downtown-orlando-ux/events/316749929/', '2026-10-15T19:00:00-04:00', 'Ten10 Brewing Company', '1010 Virginia Dr, Orlando, FL 32803, USA', 'Orlando', 'FL', '32803', 28.564001429854, -81.36589776954, 'DOUX — Downtown Orlando UX Meetup', 26, false, 'Free', 'live', 'meetup', 'https://www.meetup.com/downtown-orlando-ux/events/316749929/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
