INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Toastmasters: Mystery & Imagination', 'O''Town Toastmasters Club, Milk District, Downtown Orlando', 'General Networking', 'It''s time to get creative, and not just with this year''s costume! Public speaking includes telling stories: tales that surprise, intrigue,', 'It''s time to get creative, and not just with this year''s costume! Public speaking includes telling stories: tales that surprise, intrigue, and captivate your audience. Even serious speeches benefit from a bit of mystery and imagination. Take a little time out of your week to come join us and practice public speaking in a **SAFE TO FAIL** space. The rest of your week will be so busy. Come have a little fun and grow first! Please arrive by 11:45a, (gavel down at 12noon) Meeting''s complete by 1pm More info: https://www.meetup.com/g-otown-toastmasters-club-downtown-orlando/events/316727295/', '2026-10-27T12:00:00-04:00', 'First Unitarian Church of Orlando', '1901 E. Robinson Street', 'Orlando', 'FL', '', 28.56, -81.36, 'O''Town Toastmasters Club, Milk District, Downtown Orlando', 2, false, 'Free', 'live', 'meetup', 'https://www.meetup.com/g-otown-toastmasters-club-downtown-orlando/events/316727295/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Frankly Speaking: Live with Dr. Frankie Bashan', 'Gainesville & Worldwide Lesbian, Bi, Trans & Queer+ Events', 'Business Networking', 'Bring your questions and join Dr. Frankie for honest conversations about dating, relationships, intimacy, communication, and more. **What', 'Bring your questions and join Dr. Frankie for honest conversations about dating, relationships, intimacy, communication, and more. **What Have You Always Wanted to Ask?** What if you had a space where no dating or relationship question felt too small, too complicated, or too awkward to ask? **Frankly Speaking** is a 60-minute virtual conversation with Dr. Frankie Bashan, licensed clinical psychologist, certified sex therapist, and founder of Little Gay Book. Each session explores the real More info: https://www.meetup.com/gainesville-lesbian-bisexual-mixers-events-activities/events/315963066/', '2026-10-26T20:30:00-04:00', 'Online event', 'Online event', 'Gainesville', 'FL', '', 29.65, -82.3, 'Gainesville & Worldwide Lesbian, Bi, Trans & Queer+ Events', 0, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/gainesville-lesbian-bisexual-mixers-events-activities/events/315963066/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Tech Coffee Social', 'GNV Tech Chats', 'Business Start Ups', 'Join us for a morning coffee social and kick-start your day with great conversations and connections. Our morning coffee social is a', 'Join us for a morning coffee social and kick-start your day with great conversations and connections. Our morning coffee social is a relaxed, low-key gathering for tech professionals to socialize, collaborate, and network. Come and go as you please - drop by for a quick coffee and hello, or stick around to catch up with others. And if you''d like to stay and be productive, feel free to cowork from the coffee shop after our social. For this event, we will be at the picnic tables near Opus Coffee. More info: https://www.meetup.com/gainesville-tech-chats/events/316664324/', '2026-10-14T09:00:00-04:00', '4th Avenue Food Park', '409 SW Fourth Ave', 'Gainesville', 'FL', '', 29.65, -82.3, 'GNV Tech Chats', 5, false, 'Free', 'live', 'meetup', 'https://www.meetup.com/gainesville-tech-chats/events/316664324/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
